int check_stack_boundary_access(struct bpf_verifier_env *env, int regno,
                                int access_size, bool zero_size_allowed,
                                struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *reg = &env->cur_state->regs[regno];
    int i, slot, off, err;

    if (reg->type != PTR_TO_STACK)
        return -EACCES;

    if (access_size == 0) {
        if (zero_size_allowed)
            return 0;
        return -EACCES;
    }

    off = reg->off + reg->var_off.value;
    if (off < 0 || off + access_size > MAX_BPF_STACK)
        return -EACCES;

    for (i = 0; i < access_size; i++) {
        slot = (off + i) / BPF_REG_SIZE;
        if (slot >= MAX_BPF_STACK / BPF_REG_SIZE)
            return -EACCES;
        if (!env->cur_state->allocated_stack[slot])
            return -EACCES;
    }

    env->cur_state->stack_depth = max(env->cur_state->stack_depth, off + access_size);

    return 0;
}

