int check_stack_boundary_access(struct bpf_verifier_env *env, int regno,
                                int access_size, bool zero_size_allowed,
                                struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *reg = &env->cur_state->regs[regno];

    if (reg->type != PTR_TO_STACK)
        return -EACCES;

    if (access_size == 0) {
        if (zero_size_allowed)
            return 0;
        return -EACCES;
    }

    int offset = reg->off;
    int stack_size = reg->var_off.offset + access_size;

    if (offset < 0 && offset + access_size > 0)
        return -EACCES;

    if (offset < 0 && stack_size > BPF_STACK_RESERVED)
        return -EACCES;

    for (int i = 0; i < access_size; i++) {
        int slot = -1 - (offset + i) / BPF_REG_SIZE;
        if (slot < 0 || slot >= MAX_BPF_STACK / BPF_REG_SIZE)
            return -EACCES;
    }

    env->stack_depth = max(env->stack_depth, -offset + access_size - 1);

    return 0;
}

